/*
 * Solder Autonomous Firmware
 * Project: Obstacle Avoiding Robot Car
 * Target: Arduino Uno R3
 * Description: Generated responsive embedded control firmware.
 */

#include <Wire.h>

void setup() {
  Serial.begin(9600);
  pinMode(11, OUTPUT);
  pinMode(12, INPUT);
  pinMode(10, OUTPUT);
  Serial.println(F("SYSTEM_BOOT: OK"));
  Serial.println(F("SOLDER_PROJECT_READY"));
}

void loop() {
  digitalWrite(11, LOW); delayMicroseconds(2);
  digitalWrite(11, HIGH); delayMicroseconds(10);
  digitalWrite(11, LOW);
  long duration = pulseIn(12, HIGH, 30000);
  int distanceCm = duration > 0 ? (duration * 0.034 / 2) : 999;
  Serial.print(F("DISTANCE:")); Serial.print(distanceCm); Serial.println(F("cm"));
  if (distanceCm < 30) {
    Serial.println(F("OBJECT_DETECTED"));
  }
  // Sweep servo position
  analogWrite(10, 180);
  Serial.println(F("SERVO:SWEEP_ACTIVE"));
  Serial.println(F("OLED:FRAME_REFRESHED"));
  Serial.println(F("CYCLE_HEARTBEAT: OK"));
  delay(1000);
}
